import{_ as p,a0 as r,w as l,s as m,ao as a,I as o,x as t,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const E=JSON.parse('{"title":"Gedit插件：Embedded Terminal，让你在编辑器内使用命令行终端 | LCTT x X-CMD","titleTemplate":false,"description":"Gedit插件：Embedded Terminal，让你在编辑器内使用命令行终端 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Gedit插件：Embedded Terminal，让你在编辑器内使用命令行终端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Gedit插件：Embedded Terminal，让你在编辑器内使用命令行终端 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Embedded Terminal – A Gedit Plugin To Access The Command Line Terminal From Within The Editor Window","title":"Gedit插件：Embedded Terminal，让你在编辑器内使用命令行终端","tag":"201310","desc":""},"relativePath":"201310/Embedded Terminal – A Gedit Plugin To Access The Command Line Terminal From Within The Editor Window.md","filePath":"[post].md"}'),s={name:"201310/Embedded Terminal – A Gedit Plugin To Access The Command Line Terminal From Within The Editor Window.md"};function g(u,e,T,b,c,f){const d=r("Link");return l(),m("div",null,[e[11]||(e[11]=a(`<h1 id="gedit插件-embedded-terminal-让你在编辑器内使用命令行终端" tabindex="-1">Gedit插件：Embedded Terminal，让你在编辑器内使用命令行终端 <a class="header-anchor" href="#gedit插件-embedded-terminal-让你在编辑器内使用命令行终端" aria-label="Permalink to “Gedit插件：Embedded Terminal，让你在编辑器内使用命令行终端”">​</a></h1><p>有时候在Linux上使用基于GUI的程序，你必须在程序窗口和命令行窗口之间切换。这会消耗一些时间。将一个终端窗口嵌入到程序窗口内部是个很好的解决方案。我不知道在其他程序是否可以，但是，如果你为gedit寻找一个这样的解决方案，那么这儿有一个插件-- <strong>Embedded Terminal</strong> -- 能让你从gedit窗口内部访问命令行终端。</p><p><strong>NOTE</strong> -- 这篇文章中使用UbUntu 13.04作为例子。</p><p>###简短教程</p><p>安装了这个插件后，可以让用户很容易地在编辑文件的同时访问命令行。</p><p>这是插件启用后的gedit窗口截图：</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-embedded-terminal-colored.png" alt=""></p><p>如上，你可以看到在gedit窗口内部命令行操作与编辑文本文件集成到了一起。</p><p>###下载/安装</p><p>通过以下步骤来正确地在gedit下载安装和配置embedded terminal插件。</p><p><strong>步骤1</strong></p><p>通过命令安装gedit插件：</p><pre><code>sudo apt-get install gedit-plugins
</code></pre><p><strong>步骤2</strong></p><p>现在，在gedit窗口里，转到Edit（编辑）--&gt;Preferences（首选项）--&gt;Plugins（插件）并且启动Embedded Terminal插件。</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-embedded-terminal-enable.png" alt=""></p><p><strong>步骤3</strong></p><p>在gedit窗口中点击View（视图）--&gt;Bottom Panel（底部面板）</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-view-bottom-panel.png" alt=""></p><p>你将在gedit窗口的底部面板看到一个嵌入式终端呈现出来。</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-default-embedded-terminal.png" alt=""></p><p>唯一的问题是色调搭配不是很好，比如，白色的命令提示符在淡灰色背景下几乎看不清。接下来的步骤去修改色调搭配。</p><p><strong>步骤4</strong></p><p>打开dconf-editor，如果没有安装，通过命令来安装它：</p><pre><code>sudo apt-get install dconf-tools
</code></pre><p>安装后，用下面命令来执行：</p><pre><code>dconf-editor
</code></pre><p>在dconf editor窗口中，转到org--&gt;gnome--&gt;gedit--&gt;plugins--&gt;terminal并且取消选定use-theme-colors选项。</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-dconf-settings.png" alt=""></p><p><strong>步骤5</strong></p><p>重启gedit</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2013/09/gedit-embedded-terminal-colored.png" alt=""></p><p>可以看到，在浅色背景下的黑色的命令提示符。</p><p><strong>优点</strong></p><ul><li>从gedit窗口内部轻松访问终端</li><li>作为一个插件，它能节约任何时间</li></ul><p><strong>缺点</strong></p><ul><li>在初始化配置里色调搭配问题是个主要问题（译注，估计插件作者使用的深色配色方案的Gedit，因此没有意识到这个问题，期待以后的更新版本会解决这个问题）</li></ul><p><strong>总结</strong></p><p>无论如何，在Linux中工作总是难以避开命令行。所以，在你常用的程序窗口中嵌入一个终端是一个好多的方法。这个gedit插件是个不错的小工具，它可以帮你节省一些时间。尝试它，它值得你安装。</p><hr>`,40)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),n(d,{href:"http://mylinuxbook.com/embedded-terminal-a-gedit-plugin/"},{default:i(()=>[...e[0]||(e[0]=[t("http://mylinuxbook.com/embedded-terminal-a-gedit-plugin/",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=t("本文由 ",-1)),n(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[2]||(e[2]=[t("LCTT",-1)])]),_:1}),e[5]||(e[5]=t(" 原创翻译，",-1)),n(d,{href:"http://linux.cn/portal.php"},{default:i(()=>[...e[3]||(e[3]=[t("Linux中国",-1)])]),_:1}),e[6]||(e[6]=t(" 荣誉推出",-1))]),o("p",null,[e[9]||(e[9]=t("译者：",-1)),n(d,{href:"http://linux.cn/space/Vito"},{default:i(()=>[...e[7]||(e[7]=[t("Vito",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),n(d,{href:"http://linux.cn/space/wxy"},{default:i(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})])])}const h=p(s,[["render",g]]);export{E as __pageData,h as default};
